const payload = req.body;
try {
  const data = JSON.parse(payload);
  if (!data.id) throw new Error('missing id');
  // proceed with business logic
  res.send({ ok: true });
} catch (e) {
  res.status(400).send('Bad input');
}

function reserveSeat(user, seat) {
  if (!user) throw new Error('unauthenticated');
  if (!seat) return false;
  if (seat.status !== 'available') return false;
  // perform reservation side effects
  return true;
}

// Version A: validate at the boundary and return Result-like object
function handleRequestA(payload) {
  const parsed = safeParse(payload);
  if (!parsed.ok) return { ok: false, reason: 'invalid payload' };
  if (!isValidUser(parsed.user)) return { ok: false, reason: 'unauthorized' };
  return performBusiness(parsed.data);
}

// Version B: let helpers check deeply and use thrown errors or defaults
function handleRequestB(payload) {
  const parsed = JSON.parse(payload); // may throw
  return performBusinessWithHelpers(parsed);
}
